const arr=[10,20,30,40,50];let sum=0;for(const s of arr)if(sum+=s,30===s){print("breaking at v="+s);break}print("sum so far="+sum);const out=[];for(const s of arr)out.push(2*s);print("doubled:",out.join(","));const sparse=[1,,3],seen=[];for(const s of sparse)seen.push(String(s));print("sparse (holes become undefined):",seen.join(","));